// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(c));
        // actor must satisfy supportsToken: msg.sender must be a Bank.
        Bank bank = new Bank();
        address caller = address(bank);
        vm.assume(actor != caller);

        // first airdrop succeeds on both versions
        vm.prank(caller);
        c.airDrop();
        uint256 first = c.tokenBalance(actor == address(0) ? caller : caller);
        assertTrue(first == 20);

        // RULE: once an address holds a balance, a further airDrop must revert.
        bool ok;
        vm.prank(caller);
        try c.airDrop() { ok = true; } catch { ok = false; }
        assertTrue(!ok && c.tokenBalance(caller) == 20);
    }
}

contract Bank {
    function supportsToken() external pure returns (bytes32) {
        return (keccak256(abi.encodePacked("Nu Token")));
    }
}
